    $invLabelPages = max(1, (int) ceil($invLabelTotal / 120));
    $invLabelPage = isset($_GET['label_page']) && is_string($_GET['label_page']) && ctype_digit($_GET['label_page']) ? max(1, min($invLabelPages, (int) $_GET['label_page'])) : 1;
