<script defer src="?view_file=assets/qrcode.js"></script><script defer src="?view_file=assets/qrcode_UTF8.js"></script><script defer src="?view_file=assets/html5-qrcode.min.js"></script>
<script>
(function(){
 function ready(fn){if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',fn);}else{fn();}}
 ready(function(){
  var siteMap={},siteNameMap={};document.querySelectorAll('[data-site-code][data-site-id]').forEach(function(el){var id=el.getAttribute('data-site-id'),code=(el.getAttribute('data-site-code')||'').toUpperCase(),title=el.querySelector('.inv-label-info strong');siteMap[code]=id;siteNameMap[id]=title?title.textContent:id;});
  function portalUrl(key,value){var u=new URL(window.location.href);u.search='';u.hash='';u.searchParams.set('tab','inventory');u.searchParams.set(key,value);return u.toString();}
  function drawQr(node,value,size){try{if(typeof qrcode!=='function'){node.textContent='QR-kod kunde inte ritas';return;}var qr=qrcode(0,'M');qr.addData(value,'Byte');qr.make();node.innerHTML=qr.createSvgTag({cellSize:3,margin:2,scalable:true});node.setAttribute('aria-label','QR-kod '+(node.getAttribute('data-label')||''));}catch(e){node.textContent='QR-kod kunde inte ritas';}}
  document.querySelectorAll('[data-qr-unit]').forEach(function(node){var code=node.getAttribute('data-qr-unit')||'';drawQr(node,portalUrl('qr',code),parseInt(node.getAttribute('data-qr-size')||'78',10));});
  document.querySelectorAll('[data-qr-site]').forEach(function(node){var code=node.getAttribute('data-qr-site')||'';drawQr(node,portalUrl('siteqr',code),parseInt(node.getAttribute('data-qr-size')||'92',10));});
  var unitPrint=document.getElementById('inv-print-units'),sitePrint=document.getElementById('inv-print-sites');
  if(unitPrint)unitPrint.addEventListener('click',function(){document.body.classList.add('inv-print-units');window.print();setTimeout(function(){document.body.classList.remove('inv-print-units');},500);});
  if(sitePrint)sitePrint.addEventListener('click',function(){document.body.classList.add('inv-print-sites');window.print();setTimeout(function(){document.body.classList.remove('inv-print-sites');},500);});
  var search=document.getElementById('inv-search');if(search)search.addEventListener('input',function(){var q=search.value.toLocaleLowerCase('sv-SE').trim(),rows=[].slice.call(document.querySelectorAll('[data-inv-product]')),n=0;rows.forEach(function(row){var show=(row.getAttribute('data-search')||'').toLocaleLowerCase('sv-SE').indexOf(q)!==-1;row.hidden=!show;if(show)n++;});var no=document.getElementById('inv-no-products');if(no)no.classList.toggle('inv-hidden',n!==0||rows.length===0);});
  var operation=document.getElementById('inv-operation'),countField=document.getElementById('inv-count-article-field'),countArticle=document.getElementById('inv-count-article');function updateOperation(){var isCount=!!operation&&operation.value==='count';if(countField)countField.classList.toggle('inv-hidden',!isCount);if(countArticle){countArticle.disabled=!isCount;countArticle.required=isCount;}}if(operation){operation.addEventListener('change',updateOperation);updateOperation();}
  var scanResult=document.getElementById('inv-scan-result');function showScan(text,ok){if(!scanResult)return;scanResult.textContent=text;scanResult.classList.toggle('ok',!!ok);scanResult.classList.toggle('bad',!ok);}
  var currentSession=document.getElementById('inv-current-session'),currentSessionId=currentSession?currentSession.value:'',csrf=document.getElementById('inv-csrf'),manual=document.getElementById('inv-manual-code'),sessionSite=document.getElementById('inv-session-site'),activeSessionSite=document.getElementById('inv-session-site-id');
  if(manual){var mf=manual.closest('form');if(mf)mf.addEventListener('submit',function(ev){ev.preventDefault();submitCode(manual.value);});}
  var pending=false,lastDecoded='',lastTime=0;
  function submitCode(code){if(!currentSessionId){showScan('Starta en skanningssession innan du skannar en enhet.',false);return Promise.resolve();}if(pending)return Promise.resolve();pending=true;var body=new URLSearchParams();body.set('action','inventory_apply_scan');body.set('csrf_token',csrf?csrf.value:'');body.set('session_id',currentSessionId);body.set('code',code);return fetch('?tab=inventory',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8','Accept':'application/json'},body:body.toString(),credentials:'same-origin'}).then(function(r){return r.json().then(function(data){if(!r.ok||!data.ok)throw new Error(data.message||'Skanningen kunde inte registreras.');return data;});}).then(function(data){showScan(data.message+' '+data.article+' · '+data.code+' · saldo '+Number(data.stock).toLocaleString('sv-SE')+' · skannade '+data.scanned_count,true);if(manual)manual.value='';}).catch(function(error){showScan(error.message||'Nätverksfel. Försök igen.',false);}).finally(function(){pending=false;});}
  function decodeResult(value){var text=(value||'').trim();try{var url=new URL(text);var siteCode=url.searchParams.get('siteqr');if(siteCode)return{kind:'site',code:siteCode.toUpperCase()};var unitCode=url.searchParams.get('qr');if(unitCode)return{kind:'unit',code:unitCode};}catch(e){}text=text.toUpperCase();if(text.indexOf('SITE-')===0)return{kind:'site',code:text};return{kind:'unit',code:text};}
  function onDecoded(decoded){var now=Date.now();if(decoded===lastDecoded&&now-lastTime<1400)return;lastDecoded=decoded;lastTime=now;var parsed=decodeResult(decoded);if(parsed.kind==='site'){var target=siteMap[parsed.code];if(!target){showScan('Arbetsplats-QR känns inte igen.',false);return;}if(currentSessionId&&activeSessionSite&&activeSessionSite.value!==target){showScan('Fel arbetsplats för den öppna sessionen. Avsluta sessionen och välj rätt plats.',false);return;}if(sessionSite){sessionSite.value=target;}var globalSite=document.getElementById('inv-site-select');if(globalSite){globalSite.value=target;}showScan('Arbetsplats vald: '+(siteNameMap[target]||target),true);return;}submitCode(parsed.code);}
  var scanner=null,startBtn=document.getElementById('inv-camera-start'),stopBtn=document.getElementById('inv-camera-stop');
  if(startBtn)startBtn.addEventListener('click',function(){if(!window.Html5Qrcode){showScan('QR-skannern kunde inte laddas. Använd manuell kod eller ladda om sidan.',false);return;}if(!scanner){scanner=new Html5Qrcode('inv-qr-reader');}startBtn.disabled=true;showScan('Begär åtkomst till kameran…',true);scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:230,height:230},aspectRatio:1},onDecoded,function(){}).then(function(){if(stopBtn)stopBtn.disabled=false;showScan('Kamera aktiv. Rikta QR-koden mot rutan.',true);}).catch(function(err){startBtn.disabled=false;showScan('Kameran kunde inte starta. Kontrollera HTTPS och webbläsarens kameratillstånd.',false);});});
  if(stopBtn)stopBtn.addEventListener('click',function(){if(scanner){scanner.stop().then(function(){stopBtn.disabled=true;if(startBtn)startBtn.disabled=false;showScan('Kameran är stoppad.',true);}).catch(function(){stopBtn.disabled=true;if(startBtn)startBtn.disabled=false;});}});
  if(window.location.search){var params=new URLSearchParams(window.location.search),siteQr=params.get('siteqr'),unitQr=params.get('qr');if(siteQr&&siteMap[siteQr.toUpperCase()]&&sessionSite)sessionSite.value=siteMap[siteQr.toUpperCase()];if(unitQr&&manual)manual.value=unitQr;}
 });
})();
</script>
<?php endif; ?>
